		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		deviceCertificateId = DeviceCertificateService.getDeviceCertificateInstance()
		.createDeviceCertificate( generateNewCommand() )
		.get();

		// ---------------------------------------------
